/// The bundle as a `.pulinote` file (gzip JSON).
List<int> sampleBookFile() => gzip.encode(utf8.encode(jsonEncode(sampleBookJson())));

/// Two books in one file (`pulinote-collection`).
List<int> sampleCollectionFile() {
  final second = sampleBookJson()
    ..['id'] = 'sample-type-02'
    ..['title'] = 'SAMPLE TYPE 2회차';
  final courses = [
    for (final c in second['courses'] as List)
      {
        ...(c as Map<String, dynamic>),
        'problems': [
          for (final p in c['problems'] as List) {...(p as Map<String, dynamic>), 'id': '${p['id']}'.replaceFirst('-01-', '-02-')},
        ],
      },
  ];
  second['courses'] = courses;
  second['workbooks'] = [
    {
      ...((sampleBookJson()['workbooks'] as List).first as Map<String, dynamic>),
      'id': 'sample-type-02',
      'title': 'SAMPLE TYPE 2회차',
      'problems': [for (final c in courses) for (final p in c['problems'] as List) (p as Map)['id']],
    },
  ];
  return gzip.encode(utf8.encode(jsonEncode({
    'format': 'pulinote-collection',
    'books': [sampleBookJson(), second],
  })));
}

